<?php
if(get_option('blogname')!=='Promotions-Test'){throw new RuntimeException('Test site only.');}
function s_assert($a,$b,$name){if($a!==$b){throw new RuntimeException($name.': '.wp_json_encode($a).' != '.wp_json_encode($b));}}
Meister_Promotions_Store::install();update_option('woocommerce_currency','EUR');update_option('woocommerce_calc_taxes','yes');update_option('woocommerce_prices_include_tax','yes');update_option('woocommerce_tax_based_on','shipping');update_option('woocommerce_default_country','GR');update_option('woocommerce_tax_display_cart','incl');
$tax=WC_Tax::_insert_tax_rate(['tax_rate_country'=>'GR','tax_rate_state'=>'','tax_rate'=>'24.0000','tax_rate_name'=>'VAT','tax_rate_priority'=>1,'tax_rate_compound'=>0,'tax_rate_shipping'=>1,'tax_rate_order'=>1,'tax_rate_class'=>'']);
$zone=new WC_Shipping_Zone();$zone->set_zone_name('Disposable Greece');$zone->set_zone_order(0);$zone->add_location('GR','country');$zone->save();$instance=$zone->add_shipping_method('flat_rate');update_option('woocommerce_flat_rate_'.$instance.'_settings',['enabled'=>'yes','title'=>'Courier','tax_status'=>'taxable','cost'=>'3','type'=>'order']);WC_Cache_Helper::get_transient_version('shipping',true);
$products=[];foreach(['100','50'] as $price){$p=new WC_Product_Simple();$p->set_name('Physical fixture');$p->set_regular_price($price);$p->set_status('publish');$p->save();$products[]=$p;}
$rule=['id'=>'physical','name'=>'Physical pair','enabled'=>true,'requirements'=>array_map(static fn($p)=>['productId'=>$p->get_id(),'quantity'=>1],$products),'type'=>'percent','amount'=>'20','version'=>1];update_option('meister_promotions_rules',['physical'=>$rule]);
$input=['owner'=>'shipping-'.wp_generate_uuid4(),'email'=>'shipping@example.invalid','items'=>array_map(static fn($p)=>['productId'=>$p->get_id(),'quantity'=>1],$products),'address'=>['country'=>'GR','city'=>'Athens','postcode'=>'10000']];
$q=Meister_Promotions_Cart::quote($input);s_assert($q['subtotal'],15000,'tax-inclusive merchandise');s_assert($q['discount'],3000,'20 percent merchandise');s_assert($q['shipping'],372,'shipping retains its full 3 EUR plus VAT');s_assert($q['total'],12372,'discount then independent shipping');s_assert(array_sum(array_column($q['lines'],'total'))+$q['shipping'],$q['total'],'cent balanced');
foreach($products as $p){$p->delete(true);}$zone->delete();WC_Tax::_delete_tax_rate($tax);update_option('woocommerce_calc_taxes','no');update_option('woocommerce_prices_include_tax','no');update_option('meister_promotions_rules',[]);echo "Woo shipping/tax integration: 5 assertions passed\n";
